import{d as e,i as t}from"./index-BVdLvPw-.js";import{t as n}from"./BlogPost-BCN0DswP.js";var r=t();function i(){return(0,r.jsxs)(n,{path:`/blog-notifiable-data-breaches`,children:[(0,r.jsxs)(`p`,{children:[`Under the Notifiable Data Breaches (NDB) scheme, organisations covered by the `,(0,r.jsx)(`i`,{children:`Privacy Act 1988`}),` must notify affected individuals and the Office of the Australian Information Commissioner (OAIC) when a data breach is likely to cause serious harm.`]}),(0,r.jsx)(`p`,{children:`This guide explains who must comply, how to decide whether a breach is notifiable, what the notice must say, and the practical steps that make a breach easier to handle.`}),(0,r.jsx)(`h2`,{children:`Who it applies to`}),(0,r.jsx)(`p`,{children:`The scheme applies to organisations covered by the Privacy Act. That generally includes businesses and not-for-profits with annual turnover above $3 million, Australian Government agencies, and some smaller businesses, such as health service providers and businesses that trade in personal information.`}),(0,r.jsx)(`p`,{children:`Other smaller businesses can also be covered, for example credit reporting bodies, contracted service providers to the Australian Government, and businesses related to a larger covered organisation. If you are not sure, the OAIC has a checklist to help you work out whether the Privacy Act applies to you.`}),(0,r.jsx)(`p`,{children:`The government has said further privacy reforms are being developed, and removing or narrowing the small business exemption has been part of that discussion. At the time of writing that change is not law, but it is a good reason for smaller businesses to prepare now rather than later. Check the OAIC website for the current position.`}),(0,r.jsx)(`h2`,{children:`What is an eligible data breach?`}),(0,r.jsx)(`p`,{children:`A breach is notifiable, which the law calls an eligible data breach, when all three of these are true:`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Personal information is accessed or disclosed without authorisation, or lost in a way that makes this likely.`}),(0,r.jsx)(`li`,{children:`The breach is likely to result in serious harm to one or more individuals.`}),(0,r.jsx)(`li`,{children:`Your remedial action has not prevented that likely harm.`})]}),(0,r.jsx)(`p`,{children:`Common examples include a staff member's email account being taken over by a scammer, a laptop with client files left in a taxi, a spreadsheet of customer details emailed to the wrong person, or a database exposed online through a misconfigured setting.`}),(0,r.jsx)(`h3`,{children:`What counts as serious harm?`}),(0,r.jsx)(`p`,{children:`Serious harm can be physical, psychological, emotional, financial or reputational. When you assess it, think about the kind of information involved, how sensitive it is, who might now have it, and whether it was protected, for example by encryption. Identity documents, health records, bank details and tax file numbers usually carry a higher risk than a name and work email address.`}),(0,r.jsx)(`h3`,{children:`When remedial action changes the answer`}),(0,r.jsx)(`p`,{children:`If you act fast enough to stop serious harm being likely, the breach may not need to be notified. Say an email with client details goes to the wrong recipient, you contact them within the hour, and they confirm in writing that they deleted it without forwarding it. That may be enough. Record what happened and why you decided it was not notifiable.`}),(0,r.jsx)(`h2`,{children:`The 30-day assessment`}),(0,r.jsx)(`p`,{children:`If you suspect an eligible breach, you must carry out a reasonable and quick assessment within 30 days. The OAIC expects most assessments to be finished much sooner.`}),(0,r.jsx)(`p`,{children:`If you find there are reasonable grounds to believe an eligible breach has happened, you must notify as soon as practicable. Don't wait until the 30 days are up. A simple assessment usually follows these steps:`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Contain:`}),` reset passwords, isolate affected devices, recall emails and revoke access.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Assess:`}),` work out what information was involved, whose it was and how likely harm is.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Notify:`}),` if it is an eligible breach, tell the OAIC and affected individuals.`]}),(0,r.jsxs)(`li`,{children:[(0,r.jsx)(`b`,{children:`Review:`}),` find the cause and fix it so it doesn't happen again.`]})]}),(0,r.jsx)(`h2`,{children:`What the notification must include`}),(0,r.jsx)(`p`,{children:`The statement to the OAIC is usually made with its online Notifiable Data Breach form. It must include:`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Your organisation’s name and contact details.`}),(0,r.jsx)(`li`,{children:`A description of the breach.`}),(0,r.jsx)(`li`,{children:`The kinds of information involved.`}),(0,r.jsx)(`li`,{children:`Recommended steps individuals should take in response.`})]}),(0,r.jsx)(`p`,{children:`You then notify individuals in one of three ways: tell everyone whose information was involved, tell only those at risk of serious harm, or, if direct contact is not practicable, publish the statement on your website and take reasonable steps to make it known. Write in plain English and give practical advice, such as changing passwords, watching for scam calls or contacting IDCARE, the national identity and cyber support service.`}),(0,r.jsx)(`h2`,{children:`Common mistakes`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Assuming an encrypted or password-protected file is safe when the password was sent in the same email.`}),(0,r.jsx)(`li`,{children:`Deleting evidence while cleaning up, so you can no longer tell what was accessed.`}),(0,r.jsx)(`li`,{children:`Waiting for certainty before acting. The test is "likely", not "certain".`}),(0,r.jsx)(`li`,{children:`Forgetting that a breach at a supplier holding your data can still be your responsibility.`})]}),(0,r.jsx)(`h2`,{children:`How to prepare`}),(0,r.jsxs)(`ol`,{children:[(0,r.jsx)(`li`,{children:`Write a simple data breach response plan and name who does what.`}),(0,r.jsx)(`li`,{children:`Know where personal information is stored, and keep less of it.`}),(0,r.jsx)(`li`,{children:`Turn on multi-factor authentication and email protection.`}),(0,r.jsx)(`li`,{children:`Keep tested backups and logs so you can tell what happened.`}),(0,r.jsx)(`li`,{children:`Train staff to report suspicious emails and mistakes quickly.`})]}),(0,r.jsxs)(`p`,{children:[`Many of these controls match the `,(0,r.jsx)(e,{to:`/blog-essential-eight-guide`,children:`ASD Essential Eight strategies`}),`. If you use Microsoft 365, the security tools in `,(0,r.jsx)(e,{to:`/blog-microsoft-365-plans-compared`,children:`Microsoft 365 Business Premium`}),` can cover several of them, including device management and stronger sign-in protection.`]}),(0,r.jsx)(`h3`,{children:`A quick readiness checklist`}),(0,r.jsxs)(`ul`,{children:[(0,r.jsx)(`li`,{children:`Is there a named person who leads the response, and a backup?`}),(0,r.jsx)(`li`,{children:`Do staff know how to report a suspected breach, even out of hours?`}),(0,r.jsx)(`li`,{children:`Do you have contact details for your IT provider, insurer and lawyer in one place?`}),(0,r.jsx)(`li`,{children:`Are audit logs turned on and kept long enough to investigate?`})]}),(0,r.jsx)(`h2`,{children:`Frequently asked questions`}),(0,r.jsx)(`h3`,{children:`Do we have to report a breach if no harm has happened yet?`}),(0,r.jsx)(`p`,{children:`Yes, if serious harm is likely. The scheme is based on the risk of harm, not proof that harm has already happened.`}),(0,r.jsx)(`h3`,{children:`Our turnover is under $3 million. Can we ignore the scheme?`}),(0,r.jsx)(`p`,{children:`Not always. Health service providers, businesses that trade in personal information and some others are covered whatever their turnover. Even if you are not covered, a clear response plan protects your customers and your reputation.`}),(0,r.jsx)(`h3`,{children:`Is ransomware a notifiable breach?`}),(0,r.jsx)(`p`,{children:`It can be. If attackers could have accessed or copied personal information, you need to assess it like any other breach, even if your files were restored from backup.`}),(0,r.jsx)(`h3`,{children:`Who should we call first?`}),(0,r.jsxs)(`p`,{children:[`Start with your IT or `,(0,r.jsx)(e,{to:`/support-services`,children:`managed IT support provider`}),` to contain the incident, then your cyber insurer if you have one. ReportCyber at cyber.gov.au is the place to report cybercrime.`]}),(0,r.jsxs)(`p`,{children:[`This article is general information, not legal advice. See the OAIC website for official guidance. Our `,(0,r.jsx)(e,{to:`/cybersecurity`,children:`cybersecurity service`}),` can help you reduce the risk of a breach.`]})]})}export{i as default};